import logging
import re
import time
from typing import Union

from taf.hw.pdu.devices.tcp import TcpPdu
from taf.hw.pdu.exceptions import BadResponse, PduConnectionError
from taf.hw.pdu.devices.base import PduIdentificationType

_logger = logging.getLogger(__name__)


class ElektroAutomatik(TcpPdu):
    SUPPORTED_MODELS = ["PSI 10060-120", "PS 9080-100", "PSI 9060-170"]

    def __init__(
        self,
        host: str,
        port: int = 5025,
        timeout: Union[float, int] = 10,
        retry_timeout: Union[float, int] = 2,
    ):
        super().__init__(host, port, timeout, retry_timeout)

        _vendor, _model, _serial, _version, _rev = self.get_idn()  # Make sure device is available
        self._verify_model(_model)
        _logger.info(
            f"IDN information is vendor({_vendor}), model({_model}), "
            f"serial number({_serial}), version({_version}), revision({_rev})"
        )

    def _check_error(self) -> None:
        response = self._execute_cmd_with_retry_on_timeout("SYSTem:ERRor?\n")
        if '0,"No error"' not in response:
            raise BadResponse(f"Power supply error: {response}")

    def power_on(self, port=None) -> None:
        self._execute_cmd("SYST:LOCK ON\n")
        self._execute_cmd("OUTPut ON\n")
        time.sleep(1)
        self._execute_cmd("SYST:LOCK OFF\n")
        self._check_error()

    def power_off(self, port=None) -> None:
        self._execute_cmd("SYST:LOCK ON\n")
        self._execute_cmd("OUTPut OFF\n")
        time.sleep(1)
        self._execute_cmd("SYST:LOCK OFF\n")
        self._check_error()

    def set_voltage(self, voltage, port=None) -> None:  # type: ignore[override]
        current_voltage = self.get_voltage()
        if abs(current_voltage - voltage) > 0.1:
            self._execute_cmd(f"VOLT {voltage:.2f}\n")
            time.sleep(1)
            self._check_error()
        else:
            _logger.info(
                f"Target voltage ({voltage:.2f} V) is within 0.1 V of current voltage "
                f"({current_voltage:.2f} V); no adjustment needed."
            )

    def get_voltage(self, port=None) -> float:
        """Get the voltage from the device."""
        response = self._execute_cmd_with_retry_on_timeout("MEASure:VOLTage?\n")
        match = re.match(r"(?P<voltage>[0-9]+.?[0-9]+)\s*V", response, flags=re.IGNORECASE)
        if match:
            return float(match.group("voltage"))
        else:
            raise ValueError(f"Power supply invalid response: {response}")

    def get_current(self, port=None) -> float:
        """Get the current from the device."""
        response = self._execute_cmd_with_retry_on_timeout("MEASure:CURRent?\n")
        match = re.match(r"(?P<current>[0-9]+.?[0-9]+)\s*A", response, flags=re.IGNORECASE)
        if match:
            return float(match.group("current"))
        else:
            raise ValueError(f"Power supply invalid response: {response}")

    def get_idn(self):
        """Get the instrument information."""
        info = self.get_pdu_info()
        if info.identification_type != PduIdentificationType.SCPI_IDN:
            raise PduConnectionError()
        return [item.strip() for item in info.identifier.split(",")]

    def _verify_model(self, model):
        if model not in self.SUPPORTED_MODELS:
            _logger.warning(
                f"Model information from device '{model}' does not match the expected '{self.SUPPORTED_MODELS}'"
            )

    def _build_command(self, port, status):
        pass

    def _parse_response(self, response):
        pass

    def _port_setting(self):
        pass

    def get_port_status(self, port):
        raise NotImplementedError("Not supported by PSI device")

    def _set_port_status(self, port, status):
        raise NotImplementedError("Not supported by PSI device")
